// Indonesian administrative regions for dummy addresses and NIK region codes (FR-081 AC-3, AC-5).
// regions.json is generated by scripts/build-regions.mjs (sources and license in NOTICE.md); it is
// about 38 KB gzip, so it is loaded on demand and never part of a page's startup code.

/** [code, name, postal code]; code like `11.01.01.2001`. */
export type Village = readonly [code: string, name: string, postalCode: string];
/** [code, name, sampled villages]; code like `11.01.01`. */
export type District = readonly [code: string, name: string, villages: readonly Village[]];
/** [code, name, sampled districts]; code like `11.01`. */
export type Regency = readonly [code: string, name: string, districts: readonly District[]];
/** [code, name]; code like `11`. */
export type Province = readonly [code: string, name: string];

export interface Regions {
	readonly source: Readonly<Record<'regions' | 'postalCodes' | 'decree' | 'license', string>>;
	/** Every province, by code. */
	readonly provinces: readonly Province[];
	/** Every kabupaten/kota, by code, each with a fixed sample of districts and villages. */
	readonly regencies: readonly Regency[];
}

export async function loadRegions(): Promise<Regions> {
	// JSON imports are typed as plain arrays, not tuples; datasets.test.ts checks the shape.
	return (await import('./regions.json')).default as unknown as Regions;
}
